package vn.iotstar.example1.security; import lombok.RequiredArgsConstructor; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; import vn.iotstar.example1.entity.User; import vn.iotstar.example1.repository.UserRepository;
@Service @RequiredArgsConstructor public class CustomUserDetailsService implements UserDetailsService { private final UserRepository repo; public UserDetails loadUserByUsername(String email){ User u=repo.findByEmailWithRole(email).orElseThrow(()->new UsernameNotFoundException("Không tìm thấy tài khoản")); return org.springframework.security.core.userdetails.User.withUsername(u.getEmail()).password(u.getPassword()).roles(u.getRole().getName()).disabled(!u.isEnabled()).build(); }}
